# Chapter 23 Capacitance — part a: 23.1 to 23.4.
QE, E0 = 1.60e-19, 8.85e-12


def ser(*cs):
    return 1 / sum(1 / c for c in cs)


# ═════════════════════════ 23.1 Capacitors and capacitance (14/17/11) ═════════════════════════
lesson('23.1')
M('E', 1, 'Which expression defines the capacitance C of a capacitor?', 'C = Q/V, the charge on one plate divided by the p.d. between the plates', ['C = V/Q', 'C = QV', 'C = Q/t'], 'Capacitance is charge stored per unit potential difference.')
M('E', 1, 'Which unit is equivalent to the farad?', 'C V⁻¹', ['V C⁻¹', 'C V', 'J C⁻¹'], 'C = Q/V, so one farad is one coulomb stored per volt: 1 F = 1 C V⁻¹.')
N('E', 2, 'A 470 µF capacitor in a camera flash circuit is connected to a 6.0 V battery. How much charge does it store, in mC?', 470e-6 * 6.0 * 1000, 'mC',
  f'Q = CV = 470 × 10⁻⁶ × 6.0 = {sf(470e-6 * 6)} C. In mC: {sf(470e-6 * 6)} × 1000 = {sf(470e-6 * 6 * 1000)}', ['C1: Q = CV with C in F'], aq='Q')
N('E', 2, 'A capacitor stores 1.5 mC of charge when the p.d. across it is 3.0 V. Calculate its capacitance in µF.', 1.5e-3 / 3.0 * 1e6, 'µF',
  'C = Q/V = 1.5 × 10⁻³ ÷ 3.0 = 5.0 × 10⁻⁴ F. In µF: 5.0 × 10⁻⁴ × 10⁶ = 500', ['C1: C = Q/V'], sig=2, aq='C')
M('E', 1, 'A capacitor is charged so that one plate carries +Q. What is the charge on the other plate?', '−Q', ['+Q', 'zero', '−2Q'], 'Electrons removed from one plate are pushed onto the other, so the plates carry equal and opposite charges.')
N('E', 2, 'A 2200 µF capacitor holds a charge of 0.033 C. Calculate the p.d. across it.', 0.033 / 2200e-6, 'V',
  'V = Q/C = 0.033 ÷ 2200 × 10⁻⁶ = 15 V', ['C1: V = Q/C'], sig=2, aq='V')
M('E', 1, 'Which describes the graph of charge stored against p.d. for a capacitor?', 'A straight line through the origin, whose gradient is the capacitance', ['A curve through the origin', 'A horizontal line', 'A straight line whose gradient is 1/C'], 'Q = CV, so Q ∝ V with gradient C.')
M('E', 1, 'While a capacitor is being charged by a battery, which statement is correct?', 'Electrons flow round the circuit from one plate to the other; none cross the insulating gap', ['Electrons jump across the gap between the plates', 'Protons flow onto the positive plate', 'No current flows at any time'], 'The battery moves electrons off one plate and onto the other through the wires.')
N('E', 1, 'Express a capacitance of 4700 µF in farads.', 4700e-6, 'F', 'C = 4700 × 10⁻⁶ = 0.0047 F', [], sig=2, aq='C')
N('E', 2, 'A capacitor is charged by a steady current of 2.0 mA for 5.0 s. Calculate the charge stored.', 2.0e-3 * 5.0, 'C',
  'Q = It = 2.0 × 10⁻³ × 5.0 = 0.010 C', ['C1: Q = It'], sig=2, aq='Q')
M('E', 1, 'The p.d. across a capacitor is doubled. What happens to the charge it stores?', 'It doubles', ['It halves', 'It stays the same', 'It quadruples'], 'Q = CV and C is constant.')
N('E', 2, 'A 10 µF capacitor stores 50 µC of charge. Calculate the p.d. across it.', 50e-6 / 10e-6, 'V',
  'V = Q/C = 50 × 10⁻⁶ ÷ 10 × 10⁻⁶ = 5.0 V', ['C1: V = Q/C'], sig=2, aq='V')
M('E', 1, 'What is meant by a capacitance of one farad?', 'One coulomb of charge is stored for each volt of p.d.', ['One volt is produced by each ampere', 'One joule is stored for each coulomb', 'One coulomb flows each second'], 'C = Q/V: 1 F = 1 C V⁻¹.')
M('E', 1, 'What does the area under a graph of charging current against time represent?', 'The charge stored on the capacitor', ['The energy stored', 'The capacitance', 'The p.d. across the capacitor'], 'Q = ∫I dt, the area under the I–t graph.')
# medium
N('M', 3, 'A capacitor is charged from zero by a constant current of 50 µA for 40 s, after which the p.d. across it is 8.0 V. Calculate its capacitance in µF.', 50e-6 * 40 / 8.0 * 1e6, 'µF',
  'Q = It = 50 × 10⁻⁶ × 40 = 2.0 × 10⁻³ C. C = Q/V = 2.0 × 10⁻³ ÷ 8.0 = 2.5 × 10⁻⁴ F. In µF: 2.5 × 10⁻⁴ × 10⁶ = 250', ['C1: Q = It', 'C1: C = Q/V'], sig=2, aq='C')
N('M', 3, 'A camera-flash capacitor of 150 µF is charged to 330 V. Calculate the charge it stores, in mC.', 150e-6 * 330 * 1000, 'mC',
  f'Q = CV = 150 × 10⁻⁶ × 330 = {sf(150e-6 * 330)} C. In mC: {sf(150e-6 * 330, 4)} × 1000 = {sf(150e-6 * 330 * 1000)}', ['C1: Q = CV', 'C1: unit conversion'], aq='Q')
N('M', 4, 'A 100 µF capacitor is charged to 9.0 V. Calculate the number of electrons that have been moved from one plate to the other.' + take('e'), 100e-6 * 9.0 / QE, None,
  f'Q = CV = 100 × 10⁻⁶ × 9.0 = 9.0 × 10⁻⁴ C. N = Q/e = 9.0 × 10⁻⁴ ÷ 1.60 × 10⁻¹⁹ = {sf(9e-4 / QE)}', ['C1: Q = CV', 'C1: N = Q/e', 'B1: charge moved = charge on one plate'], aq='N')
M('M', 3, 'For a parallel-plate capacitor, C = ε₀A/d. It stays connected to a battery while its plate separation is doubled. Which row is correct?', 'C halves and Q halves', ['C halves and Q doubles', 'C doubles and Q doubles', 'C halves and Q stays the same'], 'C ∝ 1/d; V is fixed by the battery, so Q = CV halves too.', ['C1: C ∝ 1/d', 'C1: V fixed, so Q ∝ C'])
N('M', 3, 'A parallel-plate capacitor has plates of area 0.040 m² separated by 1.0 mm of air. Using C = ε₀A/d, calculate its capacitance in pF.' + take('e0'), E0 * 0.040 / 1.0e-3 * 1e12, 'pF',
  f'C = ε₀A/d = 8.85 × 10⁻¹² × 0.040 ÷ 1.0 × 10⁻³ = {sf(E0 * 0.04 / 1e-3)} F. In pF: {sf(E0 * 0.04 / 1e-3, 4)} × 10¹² = {sf(E0 * 0.04 / 1e-3 * 1e12)}', ['C1: C = ε₀A/d with d in m', 'C1: conversion to pF'], aq='C')
N('M', 3, 'The capacitance of an isolated conducting sphere of radius r is C = 4πε₀r. Calculate the capacitance of a sphere of radius 0.15 m, in pF.' + take('e0'), 4 * pi * E0 * 0.15 * 1e12, 'pF',
  f'C = 4πε₀r = 4 × π × 8.85 × 10⁻¹² × 0.15 = {sf(4 * pi * E0 * 0.15)} F. In pF: {sf(4 * pi * E0 * 0.15, 4)} × 10¹² = {sf(4 * pi * E0 * 0.15 * 1e12)}', ['C1: C = 4πε₀r', 'C1: conversion to pF'], aq='C')
M('M', 3, 'A capacitor is charged through a resistor from a battery. Why does the charging current decrease with time?', 'As the capacitor\'s p.d. rises, the p.d. across the resistor falls, so the current falls', ['The battery runs down', 'The resistor heats up and its resistance rises', 'The capacitor\'s capacitance increases'], 'I = (E − V_C)/R; V_C rises towards E.', ['C1: V_C rises', 'C1: p.d. across R = E − V_C falls'])
N('M', 3, 'The dome of a Van de Graaff generator has a capacitance of 20 pF. Calculate the charge on it when its potential is 200 kV, in µC.', 20e-12 * 200e3 * 1e6, 'µC',
  'Q = CV = 20 × 10⁻¹² × 200 × 10³ = 4.0 × 10⁻⁶ C. In µC: 4.0 × 10⁻⁶ × 10⁶ = 4.0', ['C1: Q = CV', 'C1: prefixes converted'], sig=2, aq='Q')
M('M', 3, 'What does a charged capacitor actually store?', 'Energy, with equal and opposite charges separated on its plates', ['A net charge, so the whole capacitor is charged', 'Electric current', 'Only positive charge'], 'The total charge is zero; the separation of charge stores energy in the electric field.', ['C1: net charge zero', 'C1: energy stored in field'])
N('M', 4, 'A 470 µF capacitor is charged from zero by a constant current of 20 µA. Calculate the time taken for the p.d. across it to reach 6.0 V.', 470e-6 * 6.0 / 20e-6, 's',
  f'Q = CV = 470 × 10⁻⁶ × 6.0 = {sf(470e-6 * 6)} C. t = Q/I = {sf(470e-6 * 6)} ÷ 20 × 10⁻⁶ = {sf(470e-6 * 6 / 20e-6)} s', ['C1: Q = CV', 'C1: Q = It', 'C1: rearranged for t'], aq='t')
M('M', 4, 'A charged capacitor is disconnected from its battery. A sheet of dielectric is then slid between its plates, increasing the capacitance. Which row is correct?', 'Q unchanged, V decreases', ['Q increases, V unchanged', 'Q unchanged, V increases', 'Q decreases, V decreases'], 'Isolated plates keep their charge; V = Q/C falls as C rises.', ['C1: isolated, so Q constant', 'C1: V = Q/C', 'C1: C up so V down'])
N('M', 3, 'While a capacitor charges, the current falls steadily from 3.0 mA to zero in 4.0 s, and the final p.d. is 6.0 V. Calculate the capacitance in µF.', 0.5 * 3.0e-3 * 4.0 / 6.0 * 1e6, 'µF',
  'Q = area under I–t graph = 0.5 × 3.0 × 10⁻³ × 4.0 = 6.0 × 10⁻³ C. C = 6.0 × 10⁻³ ÷ 6.0 = 1.0 × 10⁻³ F. In µF: 1.0 × 10⁻³ × 10⁶ = 1000', ['C1: Q = area of triangle', 'C1: C = Q/V'], sig=2, aq='C')
N('M', 3, 'A 10 F supercapacitor is charged to 2.7 V. For how long could it supply a steady current of 50 mA if all its charge were used?', 10 * 2.7 / 50e-3, 's',
  'Q = CV = 10 × 2.7 = 27 C. t = Q/I = 27 ÷ 50 × 10⁻³ = 540 s', ['C1: Q = CV', 'C1: t = Q/I'], sig=2, aq='t')
M('M', 3, 'A capacitor is connected through a resistor to a 6.0 V battery and left for a long time. Which describes the final state?', 'The p.d. across the capacitor is 6.0 V and the current is zero', ['The p.d. across the capacitor is 3.0 V and the current is constant', 'The current is a maximum and the p.d. is zero', 'Charge keeps flowing across the gap'], 'Charging stops when V_C equals the e.m.f., because there is then no p.d. across the resistor.', ['C1: V_C = e.m.f.', 'C1: I = 0'])
N('M', 3, 'A capacitor has plates of area 0.020 m² separated by a 0.50 mm sheet of dielectric with relative permittivity 4.0. Using C = ε₀εᵣA/d, calculate the capacitance in nF.' + take('e0'), 4.0 * E0 * 0.020 / 0.50e-3 * 1e9, 'nF',
  f'C = 4.0 × 8.85 × 10⁻¹² × 0.020 ÷ 0.50 × 10⁻³ = {sf(4 * E0 * 0.02 / 5e-4)} F. In nF: {sf(4 * E0 * 0.02 / 5e-4, 4)} × 10⁹ = {sf(4 * E0 * 0.02 / 5e-4 * 1e9)}', ['C1: C = ε₀εᵣA/d', 'C1: conversion to nF'], aq='C')
N('M', 4, 'Calculate the extra charge that must flow onto a 220 µF capacitor to raise the p.d. across it from 4.0 V to 10 V. Give your answer in mC.', 220e-6 * 6.0 * 1000, 'mC',
  f'ΔQ = CΔV = 220 × 10⁻⁶ × (10 − 4.0) = {sf(220e-6 * 6)} C. In mC: {sf(220e-6 * 6)} × 1000 = {sf(220e-6 * 6 * 1000)}', ['M1: ΔQ = CΔV', 'C1: ΔV = 6.0 V', 'C1: substitution'], aq='ΔQ')
M('M', 3, 'Why are most practical capacitances given in µF, nF or pF rather than F?', 'One farad is a very large capacitance: a parallel-plate capacitor of 1 F with a 1 mm air gap would need plates of about 10⁸ m²', ['The farad is not an SI unit', 'Capacitors cannot store more than 1 µC', 'Larger units make the voltage too high'], 'From C = ε₀A/d, A = Cd/ε₀ ≈ 1 × 10⁻³ ÷ 8.85 × 10⁻¹² ≈ 1 × 10⁸ m².', ['C1: 1 F is very large', 'C1: estimate of plate area'])
# hard
N('H', 6, 'A capacitor is charged by a constant current of 0.10 mA. The p.d. across it is recorded: t/s = 0, 10, 20, 30, 40 and V/V = 0, 2.1, 4.3, 6.4, 8.5. (a) Explain how the data show that the current is constant. (b) Calculate the gradient of the V–t graph. (c) Use the gradient to calculate the capacitance, in µF. (d) Suggest how the constant current could be maintained in practice. Give only the answer to (c).', 0.10e-3 / (8.5 / 40) * 1e6, 'µF',
  f'(a) V rises by about 2.1 V every 10 s: a straight line through the origin, so charge is added at a steady rate. (b) Gradient = 8.5 ÷ 40 = {sf(8.5 / 40)} V s⁻¹. (c) Q = CV and Q = It, so I = C × gradient: C = 0.10 × 10⁻³ ÷ {sf(8.5 / 40, 4)} = {sf(1e-4 / (8.5 / 40))} F. In µF: {sf(1e-4 / (8.5 / 40), 4)} × 10⁶ = {sf(1e-4 / (8.5 / 40) * 1e6)}. (d) Reduce a variable resistor gradually to keep the ammeter reading steady.',
  ['B1: linear V–t means constant rate of charging', 'C1: gradient', 'M1: I = C dV/dt', 'C1: substitution', 'B1: adjust a variable resistor'], aq='C')
N('H', 5, 'A parallel-plate air capacitor has plates of area 0.25 m² separated by 2.0 mm, so that C = ε₀A/d. (a) Calculate its capacitance in nF. (b) It is connected to a 500 V supply. Calculate the charge stored. (c) Calculate the electric field strength between the plates. Give only the answer to (a).' + take('e0'), E0 * 0.25 / 2.0e-3 * 1e9, 'nF',
  f'(a) C = 8.85 × 10⁻¹² × 0.25 ÷ 2.0 × 10⁻³ = {sf(E0 * 0.25 / 2e-3)} F. In nF: {sf(E0 * 0.25 / 2e-3, 4)} × 10⁹ = {sf(E0 * 0.25 / 2e-3 * 1e9)}. (b) Q = CV = {sf(E0 * 0.25 / 2e-3, 4)} × 500 = {sf(E0 * 0.25 / 2e-3 * 500)} C. (c) E = V/d = 500 ÷ 2.0 × 10⁻³ = 2.5 × 10⁵ V m⁻¹.',
  ['C1: C = ε₀A/d', 'C1: conversion to nF', 'C1: Q = CV', 'C1: E = V/d'], aq='C')
N('H', 6, 'A thundercloud and the ground can be modelled as a parallel-plate capacitor. The cloud base has an area of 1.0 × 10⁷ m² and is 1.0 km above the ground. (a) Using C = ε₀A/d, calculate the capacitance. (b) The cloud base carries a charge of 20 C. Calculate the p.d. between cloud and ground. (c) Calculate the average field strength and compare it with the breakdown field of air, 3.0 × 10⁶ V m⁻¹. Give only the answer to (b).' + take('e0'), 20 / (E0 * 1.0e7 / 1000), 'V',
  f'(a) C = 8.85 × 10⁻¹² × 1.0 × 10⁷ ÷ 1000 = {sf(E0 * 1e7 / 1000)} F. (b) V = Q/C = 20 ÷ {sf(E0 * 1e7 / 1000, 4)} = {sf(20 / (E0 * 1e7 / 1000))} V. (c) E = {sf(20 / (E0 * 1e7 / 1000), 4)} ÷ 1000 = {sf(20 / (E0 * 1e7 / 1000) / 1000)} V m⁻¹, about a tenth of the breakdown value, so breakdown must start where the field is locally stronger.',
  ['C1: C = ε₀A/d', 'A1: C value', 'C1: V = Q/C', 'C1: E = V/d', 'B1: comparison with breakdown field'], aq='V')
N('H', 5, 'A student uses a coulombmeter to measure the charge on a capacitor at different p.d.s: V/V = 2.0, 4.0, 6.0, 8.0 and Q/µC = 0.94, 1.90, 2.80, 3.78. (a) Describe the relationship shown. (b) Calculate the gradient of the Q–V graph using the first and last points. (c) State the capacitance in µF. (d) Suggest why the line may not pass exactly through the origin. Give only the answer to (c).', (3.78 - 0.94) / (8.0 - 2.0), 'µF',
  f'(a) Q is proportional to V. (b) Gradient = (3.78 − 0.94) ÷ (8.0 − 2.0) = {sf(2.84 / 6)} µC V⁻¹. (c) C = gradient = {sf(2.84 / 6)} µF. (d) Charge leaks from the capacitor or the meter before the reading is taken, or the meter has a zero error.',
  ['B1: Q ∝ V', 'C1: gradient', 'M1: C = gradient', 'B1: leakage or zero error'], aq='C')
N('H', 6, 'An isolated metal sphere of radius 0.10 m in air has capacitance C = 4πε₀r. The field at its surface is V/r, and air breaks down at 3.0 × 10⁶ V m⁻¹. (a) Calculate the capacitance in pF. (b) Calculate the largest potential the sphere can reach. (c) Calculate the largest charge it can hold, in µC. Give only the answer to (c).' + take('e0'), 4 * pi * E0 * 0.10 * 3.0e6 * 0.10 * 1e6, 'µC',
  f'(a) C = 4 × π × 8.85 × 10⁻¹² × 0.10 = {sf(4 * pi * E0 * 0.1)} F. In pF: {sf(4 * pi * E0 * 0.1, 4)} × 10¹² = {sf(4 * pi * E0 * 0.1 * 1e12)}. (b) V = Er = 3.0 × 10⁶ × 0.10 = 3.0 × 10⁵ V. (c) Q = CV = {sf(4 * pi * E0 * 0.1, 4)} × 3.0 × 10⁵ = {sf(4 * pi * E0 * 0.1 * 3e5)} C. In µC: {sf(4 * pi * E0 * 0.1 * 3e5, 4)} × 10⁶ = {sf(4 * pi * E0 * 0.1 * 3e5 * 1e6)}',
  ['C1: C = 4πε₀r', 'C1: V = Er', 'C1: Q = CV', 'C1: conversion to µC', 'M1: maximum set by breakdown field'], aq='Q')
N('H', 5, 'A bank of supercapacitors with total capacitance 3000 F is charged to 2.7 V. (a) Calculate the charge stored. (b) Calculate the number of electrons moved during charging. (c) The bank is discharged to 1.35 V in 60 s. Calculate the average current. Give only the answer to (c).' + take('e'), 3000 * (2.7 - 1.35) / 60, 'A',
  f'(a) Q = CV = 3000 × 2.7 = 8100 C. (b) N = 8100 ÷ 1.60 × 10⁻¹⁹ = {sf(8100 / QE)}. (c) ΔQ = 3000 × (2.7 − 1.35) = 4050 C, so I = 4050 ÷ 60 = 67.5 A',
  ['C1: Q = CV', 'C1: N = Q/e', 'M1: ΔQ = CΔV', 'C1: I = ΔQ/t'], aq='I')
N('H', 5, 'An air-filled capacitor of 200 pF stays connected to a 50 V supply while a slab of dielectric of relative permittivity 3.0 is inserted, filling the gap. (a) Calculate the charge before the slab is inserted. (b) Calculate the new capacitance. (c) Calculate the extra charge that flows from the supply, in nC. Give only the answer to (c).', (600e-12 - 200e-12) * 50 * 1e9, 'nC',
  '(a) Q₁ = 200 × 10⁻¹² × 50 = 1.0 × 10⁻⁸ C. (b) C₂ = 3.0 × 200 = 600 pF. (c) Q₂ = 600 × 10⁻¹² × 50 = 3.0 × 10⁻⁸ C. ΔQ = 3.0 × 10⁻⁸ − 1.0 × 10⁻⁸ = 2.0 × 10⁻⁸ C. In nC: 2.0 × 10⁻⁸ × 10⁹ = 20',
  ['C1: Q = CV', 'C1: C × εᵣ', 'M1: V fixed by supply', 'C1: ΔQ'], sig=2, aq='ΔQ')
N('H', 5, 'A 60 pF parallel-plate capacitor is charged to 120 V and then disconnected from the supply. Its plate separation is then increased to four times its original value (C = ε₀A/d). (a) Calculate the charge on the capacitor. (b) Calculate the new capacitance. (c) Calculate the new p.d. between the plates. Give only the answer to (c).', 120 * 4, 'V',
  '(a) Q = CV = 60 × 10⁻¹² × 120 = 7.2 × 10⁻⁹ C. (b) C ∝ 1/d, so C = 60 ÷ 4 = 15 pF. (c) Q is unchanged because the plates are isolated: V = Q/C = 7.2 × 10⁻⁹ ÷ 15 × 10⁻¹² = 480 V',
  ['C1: Q = CV', 'C1: C ∝ 1/d', 'M1: Q constant when isolated', 'C1: V = Q/C'], sig=2, aq='V')
N('H', 6, 'A capacitor is charged from a 9.0 V supply through a resistor. The current is recorded: t/s = 0, 10, 20, 30 and I/mA = 2.0, 1.2, 0.72, 0.43. At t = 30 s the p.d. across the capacitor is 7.05 V. (a) Use the trapezium rule to estimate the charge that flowed in the first 30 s, in mC. (b) Use your answer to estimate the capacitance, in µF. (c) Explain whether your estimate of the charge is too high or too low. Give only the answer to (b).', 10 * ((2.0 + 1.2) / 2 + (1.2 + 0.72) / 2 + (0.72 + 0.43) / 2) * 1e-3 / 7.05 * 1e6, 'µF',
  f'(a) Q ≈ 10 × (2.0 + 1.2) ÷ 2 + 10 × (1.2 + 0.72) ÷ 2 + 10 × (0.72 + 0.43) ÷ 2 = {sf(10 * ((2.0 + 1.2) / 2 + (1.2 + 0.72) / 2 + (0.72 + 0.43) / 2))} mC. (b) C = Q/V = {sf(10 * ((2.0 + 1.2) / 2 + (1.2 + 0.72) / 2 + (0.72 + 0.43) / 2), 4)} × 10⁻³ ÷ 7.05 = {sf(31.35e-3 / 7.05)} F. In µF: {sf(31.35e-3 / 7.05, 4)} × 10⁶ = {sf(31.35e-3 / 7.05 * 1e6)}. (c) Too high: the curve bends below the straight lines joining the points, so the trapezia include extra area.',
  ['C1: area under I–t graph = charge', 'C1: trapezium rule applied', 'M1: C = Q/V', 'C1: conversion to µF', 'B1: overestimate, curve below chords'], aq='C')
N('H', 5, 'A 2.0 µF capacitor is charged to 12 V. (a) Calculate the charge on each plate. (b) Calculate the number of electrons that moved through the circuit from one plate to the other. (c) Explain why the total charge on the capacitor is zero, even though it is "charged". Give only the answer to (b).' + take('e'), 2.0e-6 * 12 / QE, None,
  f'(a) Q = CV = 2.0 × 10⁻⁶ × 12 = 2.4 × 10⁻⁵ C, +2.4 × 10⁻⁵ C on one plate and −2.4 × 10⁻⁵ C on the other. (b) N = 2.4 × 10⁻⁵ ÷ 1.60 × 10⁻¹⁹ = {sf(2.4e-5 / QE)}. (c) Every electron added to one plate came from the other, so the charges are equal and opposite and sum to zero.',
  ['C1: Q = CV', 'C1: N = Q/e', 'B1: equal and opposite charges', 'B1: electrons moved, not created'], aq='N')
N('H', 6, 'In a condenser microphone, the diaphragm and a fixed back-plate form a parallel-plate capacitor (C = ε₀A/d) of area 1.0 × 10⁻⁴ m² and separation 20 µm, held at 50 V. A sound wave pushes the diaphragm so that the separation becomes 19 µm. (a) Calculate the capacitance at 20 µm. (b) Calculate the capacitance at 19 µm. (c) Calculate the charge that flows onto the capacitor, in pC. (d) Explain how this produces an electrical signal. Give only the answer to (c).' + take('e0'), 50 * (E0 * 1e-4 / 19e-6 - E0 * 1e-4 / 20e-6) * 1e12, 'pC',
  f'(a) C₁ = 8.85 × 10⁻¹² × 1.0 × 10⁻⁴ ÷ 20 × 10⁻⁶ = {sf(E0 * 1e-4 / 20e-6)} F. (b) C₂ = 8.85 × 10⁻¹² × 1.0 × 10⁻⁴ ÷ 19 × 10⁻⁶ = {sf(E0 * 1e-4 / 19e-6)} F. (c) ΔQ = VΔC = 50 × ({sf(E0 * 1e-4 / 19e-6, 4)} − {sf(E0 * 1e-4 / 20e-6, 4)}) = {sf(50 * (E0 * 1e-4 / 19e-6 - E0 * 1e-4 / 20e-6))} C. In pC: {sf(50 * (E0 * 1e-4 / 19e-6 - E0 * 1e-4 / 20e-6), 4)} × 10¹² = {sf(50 * (E0 * 1e-4 / 19e-6 - E0 * 1e-4 / 20e-6) * 1e12)}. (d) As the diaphragm vibrates, charge flows on and off the plates; this current through a resistor gives a p.d. that follows the sound.',
  ['C1: C at 20 µm', 'C1: C at 19 µm', 'M1: ΔQ = VΔC', 'C1: conversion to pC', 'B1: changing charge gives current signal'], aq='ΔQ')

# ═════════════════════════ 23.2 Energy stored in a capacitor (17/16/9) ═════════════════════════
lesson('23.2')
M('E', 1, 'Which expression gives the energy W stored in a capacitor carrying charge Q at p.d. V?', 'W = ½QV', ['W = QV', 'W = 2QV', 'W = Q/V'], 'The p.d. rises from 0 to V while charge is added, so the average p.d. is V/2.')
N('E', 2, 'A 2200 µF smoothing capacitor in a power supply is at 9.0 V. How much energy does it hold?', 0.5 * 2200e-6 * 9.0 ** 2, 'J',
  f'W = ½CV² = 0.5 × 2200 × 10⁻⁶ × 9.0² = {sf(0.5 * 2200e-6 * 81)} J', ['C1: W = ½CV²'], aq='W')
N('E', 2, 'A defibrillator capacitor of 32 µF is charged to 5.0 kV. Calculate the energy stored.', 0.5 * 32e-6 * 5.0e3 ** 2, 'J',
  'W = ½CV² = 0.5 × 32 × 10⁻⁶ × (5.0 × 10³)² = 400 J', ['C1: W = ½CV² with units converted'], sig=2, aq='W')
M('E', 1, 'What does the area under a graph of p.d. (y-axis) against charge (x-axis) for a capacitor represent?', 'The energy stored', ['The capacitance', 'The current', 'The time constant'], 'W = ∫V dQ, the area under the V–Q line: a triangle of area ½QV.')
N('E', 2, 'A camera flash capacitor holds a charge of 3.0 mC at a p.d. of 6.0 V. Calculate the energy it stores, in mJ.', 0.5 * 3.0e-3 * 6.0 * 1000, 'mJ',
  'W = ½QV = 0.5 × 3.0 × 10⁻³ × 6.0 = 9.0 × 10⁻³ J. In mJ: 9.0 × 10⁻³ × 1000 = 9.0', ['C1: W = ½QV'], sig=2, aq='W')
M('E', 1, 'The p.d. across a capacitor is doubled. What happens to the energy stored?', 'It becomes four times as large', ['It doubles', 'It halves', 'It stays the same'], 'W = ½CV², so W ∝ V².')
N('E', 2, 'A 0.010 F capacitor carries a charge of 0.020 C. Calculate the energy stored.', 0.020 ** 2 / (2 * 0.010), 'J',
  'W = Q²/2C = 0.020² ÷ (2 × 0.010) = 0.020 J', ['C1: W = Q²/2C'], sig=2, aq='W')
M('E', 1, 'A capacitor is charged fully from a battery through a resistor. What fraction of the energy supplied by the battery ends up stored in the capacitor?', 'One half', ['All of it', 'One quarter', 'None of it'], 'The battery supplies QV; the capacitor stores ½QV; the rest is dissipated in the resistance.')
N('E', 2, 'Calculate the p.d. needed to store 1.0 J of energy in a 1000 µF capacitor.', sqrt(2 * 1.0 / 1000e-6), 'V',
  f'V = √(2W/C) = √(2 × 1.0 ÷ 1000 × 10⁻⁶) = {sf(sqrt(2 / 1e-3))} V', ['C1: rearranged W = ½CV²'], aq='V')
M('E', 1, 'Which graph of energy stored (y-axis) against p.d. (x-axis) is correct for a capacitor?', 'A curve through the origin getting steeper (a parabola)', ['A straight line through the origin', 'A horizontal line', 'A curve that levels off'], 'W = ½CV² is a square law.')
N('E', 2, 'A 1.0 F supercapacitor is charged to 5.0 V. Calculate the energy stored.', 0.5 * 1.0 * 5.0 ** 2, 'J',
  'W = ½CV² = 0.5 × 1.0 × 5.0² = 12.5 J', ['C1: W = ½CV²'], aq='W')
M('E', 1, 'Where is the energy of a charged capacitor stored?', 'In the electric field between the plates', ['In the wires connecting it', 'In the metal of the plates as heat', 'In the battery that charged it'], 'Separating the charges creates a field between the plates; the energy is associated with that field.')
N('E', 2, 'A capacitor stores 0.50 J when the p.d. across it is 100 V. Calculate its capacitance in µF.', 2 * 0.50 / 100 ** 2 * 1e6, 'µF',
  'C = 2W/V² = 2 × 0.50 ÷ 100² = 1.0 × 10⁻⁴ F. In µF: 1.0 × 10⁻⁴ × 10⁶ = 100', ['C1: C = 2W/V²'], sig=2, aq='C')
M('E', 1, 'The charge on a capacitor is halved while its capacitance stays the same. What happens to the energy stored?', 'It becomes one quarter of its original value', ['It halves', 'It doubles', 'It stays the same'], 'W = Q²/2C, so W ∝ Q².')
N('E', 1, 'How much energy is held by a 1.0 µF capacitor whose plates have a p.d. of 100 V between them?', 0.5 * 1.0e-6 * 100 ** 2, 'J',
  'W = ½CV² = 0.5 × 1.0 × 10⁻⁶ × 100² = 0.0050 J', [], sig=2, aq='W')
N('E', 2, 'A camera flash tube receives 0.80 J from its capacitor in 1.0 ms. Calculate the average power of the flash.', 0.80 / 1.0e-3, 'W',
  'P = W/t = 0.80 ÷ 1.0 × 10⁻³ = 800 W', ['C1: P = W/t'], sig=2, aq='P')
M('E', 1, 'Compared with a rechargeable battery of similar size, what is the main advantage of a capacitor as an energy store?', 'It can release its energy very quickly', ['It stores much more energy', 'It keeps a constant p.d. as it discharges', 'It never loses charge'], 'Capacitors deliver high power for a short time; batteries store more energy at a steadier p.d.')
# medium
N('M', 3, 'A 470 µF capacitor is charged from 6.0 V to 12 V. Calculate the increase in the energy stored.', 0.5 * 470e-6 * (12 ** 2 - 6.0 ** 2), 'J',
  f'ΔW = ½C(V₂² − V₁²) = 0.5 × 470 × 10⁻⁶ × (12² − 6.0²) = {sf(0.5 * 470e-6 * 108)} J', ['M1: difference of ½CV² values', 'C1: substitution'], aq='ΔW')
N('M', 3, 'A defibrillator must deliver 200 J from a 40 µF capacitor. Calculate the p.d. to which the capacitor must be charged, in kV.', sqrt(2 * 200 / 40e-6) / 1000, 'kV',
  f'V = √(2W/C) = √(2 × 200 ÷ 40 × 10⁻⁶) = {sf(sqrt(400 / 40e-6))} V. In kV: {sf(sqrt(400 / 40e-6), 4)} ÷ 1000 = {sf(sqrt(400 / 40e-6) / 1000)}', ['C1: V = √(2W/C)', 'C1: conversion to kV'], aq='V')
N('M', 4, 'A 100 µF capacitor is charged to 12 V by a battery through a resistor. Calculate the energy dissipated in the resistor, in mJ.', (100e-6 * 12 * 12 - 0.5 * 100e-6 * 12 ** 2) * 1000, 'mJ',
  'Charge moved Q = CV = 100 × 10⁻⁶ × 12 = 1.2 × 10⁻³ C. Energy from battery = QV = 1.2 × 10⁻³ × 12 = 0.0144 J. Energy stored = ½QV = 0.5 × 1.2 × 10⁻³ × 12 = 0.0072 J. Dissipated = 0.0144 − 0.0072 = 0.0072 J. In mJ: 0.0072 × 1000 = 7.2',
  ['C1: battery supplies QV', 'C1: stored ½QV', 'M1: difference dissipated'], sig=2, aq='W')
M('M', 3, 'A graph of p.d. against charge for a capacitor is a straight line from the origin to 8.0 V at 4.0 mC. What energy is stored at 8.0 V?', '16 mJ', ['32 mJ', '8.0 mJ', '0.50 mJ'], 'Energy = area of triangle = ½ × 4.0 × 10⁻³ × 8.0 = 0.016 J. 32 mJ uses QV without the ½.', ['C1: area under V–Q graph', 'C1: ½QV'])
N('M', 3, 'A 4700 µF capacitor discharges from 9.0 V to 3.0 V. Calculate the energy it releases.', 0.5 * 4700e-6 * (9.0 ** 2 - 3.0 ** 2), 'J',
  f'ΔW = 0.5 × 4700 × 10⁻⁶ × (9.0² − 3.0²) = {sf(0.5 * 4700e-6 * 72)} J', ['M1: difference of ½CV²', 'C1: substitution'], aq='ΔW')
N('M', 4, 'A camera flash uses a 150 µF capacitor charged to 330 V for each flash. Its battery stores 1.0 × 10⁴ J, and charging the capacitor is 60 % efficient. Estimate the number of flashes the battery can provide.', 0.60 * 1.0e4 / (0.5 * 150e-6 * 330 ** 2), None,
  f'Energy per flash = 0.5 × 150 × 10⁻⁶ × 330² = {sf(0.5 * 150e-6 * 330 ** 2)} J. Useful energy = 0.60 × 1.0 × 10⁴ = 6000 J. Number = 6000 ÷ {sf(0.5 * 150e-6 * 330 ** 2, 4)} = {sf(6000 / (0.5 * 150e-6 * 330 ** 2))}',
  ['C1: ½CV² per flash', 'C1: 60 % of battery energy', 'C1: number = useful energy ÷ energy per flash'], aq='number')
M('M', 4, 'Capacitor A has capacitance C and is charged to 2V. Capacitor B has capacitance 2C and is charged to V. What is (energy in A) ÷ (energy in B)?', '2', ['1', '½', '4'], 'W_A = ½C(2V)² = 2CV²; W_B = ½(2C)V² = CV²; the ratio is 2.', ['C1: W_A = 2CV²', 'C1: W_B = CV²', 'C1: ratio'])
N('M', 3, 'A capacitor stores 0.36 J of energy when the p.d. across it is 12 V. Calculate the charge on it.', 2 * 0.36 / 12, 'C',
  'W = ½QV, so Q = 2W/V = 2 × 0.36 ÷ 12 = 0.060 C', ['C1: W = ½QV', 'C1: rearranged'], sig=2, aq='Q')
N('M', 4, 'A 0.10 F capacitor charged to 5.0 V powers a clock that needs 2.0 mW. The clock stops working when the p.d. falls to 2.0 V. Assuming constant power, estimate how long the clock runs.', 0.5 * 0.10 * (5.0 ** 2 - 2.0 ** 2) / 2.0e-3, 's',
  'Energy available = 0.5 × 0.10 × (5.0² − 2.0²) = 1.05 J. t = W/P = 1.05 ÷ 2.0 × 10⁻³ = 525 s', ['C1: ½CV² at each p.d.', 'M1: energy difference available', 'C1: t = W/P'], aq='t')
M('M', 3, 'A capacitor is charged from zero by a constant current. How does the energy stored vary with time?', 'In proportion to t², because V ∝ t and W ∝ V²', ['In proportion to t', 'It stays constant', 'In proportion to √t'], 'Q = It, so V = It/C and W = ½CV² = I²t²/2C.', ['C1: V ∝ t', 'C1: W ∝ V²'])
N('M', 3, 'Calculate the charge on a 2000 µF capacitor that stores 50 J.', sqrt(2 * 50 * 2000e-6), 'C',
  f'W = Q²/2C, so Q = √(2WC) = √(2 × 50 × 2000 × 10⁻⁶) = {sf(sqrt(2 * 50 * 2e-3))} C', ['C1: W = Q²/2C', 'C1: rearranged'], aq='Q')
N('M', 3, 'The p.d. across a capacitor is increased from 4.0 V to 12 V. By what factor does the energy stored increase?', (12 / 4.0) ** 2, None,
  'W ∝ V², so the factor = (12 ÷ 4.0)² = 9.0', ['C1: W ∝ V²', 'C1: ratio squared'], sig=2, aq='factor')
N('M', 4, 'A defibrillator delivers 360 J to a patient in 5.0 ms. Calculate the average power delivered, in kW.', 360 / 5.0e-3 / 1000, 'kW',
  'P = W/t = 360 ÷ 5.0 × 10⁻³ = 7.2 × 10⁴ W. In kW: 7.2 × 10⁴ ÷ 1000 = 72', ['C1: P = W/t', 'C1: t in s', 'C1: conversion to kW'], sig=2, aq='P')
M('M', 3, 'A capacitor is connected to a fixed supply. Which change would exactly double the energy stored?', 'Doubling the capacitance', ['Doubling the p.d.', 'Halving the capacitance', 'Doubling the charge with the same capacitance'], 'At fixed V, W = ½CV² ∝ C. Doubling V or Q at fixed C quadruples W.', ['C1: W ∝ C at fixed V', 'C1: W ∝ V² rules out the others'])
N('M', 3, 'A thundercloud and the ground act as a capacitor of 1.0 × 10⁻⁷ F charged to 1.0 × 10⁸ V. Calculate the energy stored.', 0.5 * 1.0e-7 * 1.0e8 ** 2, 'J',
  'W = ½CV² = 0.5 × 1.0 × 10⁻⁷ × (1.0 × 10⁸)² = 5.0 × 10⁸ J', ['C1: W = ½CV²', 'C1: substitution'], sig=2, aq='W')
N('M', 3, 'A 3000 F supercapacitor has a mass of 0.50 kg and can be charged to 2.7 V. Calculate the energy stored per kilogram of capacitor.', 0.5 * 3000 * 2.7 ** 2 / 0.50, 'J kg⁻¹',
  f'W = 0.5 × 3000 × 2.7² = {sf(0.5 * 3000 * 2.7 ** 2)} J. Per kilogram: {sf(0.5 * 3000 * 2.7 ** 2, 4)} ÷ 0.50 = {sf(0.5 * 3000 * 2.7 ** 2 / 0.5)} J kg⁻¹', ['C1: W = ½CV²', 'C1: ÷ mass'], aq='energy per kg')
# hard
N('H', 6, 'A student charges a capacitor and records: V/V = 0, 2.5, 5.0, 7.5, 10.0 and Q/mC = 0, 1.1, 2.2, 3.3, 4.4. (a) Calculate the capacitance in µF. (b) Use the area under the V–Q graph to find the energy stored at 10.0 V. (c) Calculate the energy added as the p.d. rises from 5.0 V to 10.0 V, in mJ. (d) Explain why more energy is added in the second 5.0 V than in the first. Give only the answer to (c).', (0.5 * 4.4e-3 * 10.0 - 0.5 * 2.2e-3 * 5.0) * 1000, 'mJ',
  '(a) C = Q/V = 4.4 × 10⁻³ ÷ 10.0 = 4.4 × 10⁻⁴ F, which is 440 µF. (b) Area = 0.5 × 4.4 × 10⁻³ × 10.0 = 0.022 J. (c) At 5.0 V: 0.5 × 2.2 × 10⁻³ × 5.0 = 0.0055 J. ΔW = 0.022 − 0.0055 = 0.0165 J. In mJ: 0.0165 × 1000 = 16.5. (d) Each extra coulomb is pushed on against a larger p.d., so more work is done per coulomb.',
  ['C1: C = gradient', 'C1: area of triangle', 'C1: energy at 5.0 V', 'M1: difference of areas', 'B1: work per coulomb rises with V'], aq='ΔW')
N('H', 6, 'A 100 µF capacitor charged to 12 V is connected across an uncharged 50 µF capacitor. (a) Calculate the initial energy stored. (b) Calculate the common p.d. after connection. (c) Calculate the total energy stored after connection. (d) Calculate the energy lost, in mJ, and state where it goes. Give only the energy lost.', (0.5 * 100e-6 * 144 - 0.5 * 150e-6 * 8.0 ** 2) * 1000, 'mJ',
  '(a) W₁ = 0.5 × 100 × 10⁻⁶ × 12² = 7.2 × 10⁻³ J. (b) Charge is conserved: Q = 100 × 10⁻⁶ × 12 = 1.2 × 10⁻³ C, so V = 1.2 × 10⁻³ ÷ 150 × 10⁻⁶ = 8.0 V. (c) W₂ = 0.5 × 150 × 10⁻⁶ × 8.0² = 4.8 × 10⁻³ J. (d) Loss = 7.2 × 10⁻³ − 4.8 × 10⁻³ = 2.4 × 10⁻³ J. In mJ: 2.4 × 10⁻³ × 1000 = 2.4. It is dissipated as heat in the connecting wires (and some as electromagnetic radiation).',
  ['C1: initial ½CV²', 'M1: charge conserved', 'C1: common V', 'C1: final energy', 'B1: heating in wires'], sig=2, aq='W')
N('H', 5, 'A defibrillator must deliver 150 J from a 50 µF capacitor. (a) Calculate the p.d. to which the capacitor must be charged. (b) Calculate the charge stored. (c) The capacitor discharges through the patient in 4.0 ms. Calculate the average current. Give only the answer to (a).', sqrt(2 * 150 / 50e-6), 'V',
  f'(a) V = √(2W/C) = √(2 × 150 ÷ 50 × 10⁻⁶) = {sf(sqrt(300 / 50e-6))} V. (b) Q = CV = 50 × 10⁻⁶ × {sf(sqrt(300 / 50e-6), 4)} = {sf(50e-6 * sqrt(300 / 50e-6))} C. (c) I = Q/t = {sf(50e-6 * sqrt(300 / 50e-6), 4)} ÷ 4.0 × 10⁻³ = {sf(50e-6 * sqrt(300 / 50e-6) / 4e-3)} A',
  ['C1: V = √(2W/C)', 'C1: Q = CV', 'C1: I = Q/t', 'M1: rearrangement of W = ½CV²'], aq='V')
N('H', 5, '(a) Use a graph of p.d. against charge to show that the energy stored in a capacitor is ½CV². (b) A pulsed laser uses a 2.0 µF capacitor charged to 6.0 kV. Calculate the energy stored. (c) The capacitor is charged in 3.0 s by a constant current. Calculate this current, in mA. Give only the answer to (c).', 2.0e-6 * 6.0e3 / 3.0 * 1000, 'mA',
  '(a) The graph is a straight line from the origin to (Q, V); the energy is the area ½QV, and Q = CV gives ½CV². (b) W = 0.5 × 2.0 × 10⁻⁶ × (6.0 × 10³)² = 36 J. (c) Q = CV = 2.0 × 10⁻⁶ × 6.0 × 10³ = 0.012 C. I = Q/t = 0.012 ÷ 3.0 = 4.0 × 10⁻³ A. In mA: 4.0 × 10⁻³ × 1000 = 4.0',
  ['M1: area under V–Q graph', 'B1: ½QV = ½CV²', 'C1: energy', 'C1: Q = CV then I = Q/t'], sig=2, aq='I')
N('H', 5, 'A camera flash circuit charges a 220 µF capacitor to 300 V. (a) Calculate the charge stored. (b) Calculate the energy stored. (c) The flash lasts 1.0 ms. Calculate the average power of the flash, in kW. (d) Explain why the flash tube is not powered directly from the 1.5 V battery. Give only the answer to (c).', 0.5 * 220e-6 * 300 ** 2 / 1.0e-3 / 1000, 'kW',
  f'(a) Q = 220 × 10⁻⁶ × 300 = {sf(220e-6 * 300)} C. (b) W = 0.5 × 220 × 10⁻⁶ × 300² = {sf(0.5 * 220e-6 * 9e4)} J. (c) P = {sf(0.5 * 220e-6 * 9e4)} ÷ 1.0 × 10⁻³ = {sf(0.5 * 220e-6 * 9e4 / 1e-3)} W. In kW: {sf(0.5 * 220e-6 * 9e4 / 1e-3)} ÷ 1000 = {sf(0.5 * 220e-6 * 9e4 / 1e-3 / 1000)}. (d) The battery\'s internal resistance and low p.d. cannot supply such a large power; the capacitor collects energy slowly and releases it quickly.',
  ['C1: Q = CV', 'C1: W = ½CV²', 'C1: P = W/t', 'B1: battery cannot deliver high power'], aq='P')
N('H', 6, 'A student measures the energy stored in a capacitor at several p.d.s: V/V = 2.0, 4.0, 6.0, 8.0 and W/mJ = 0.94, 3.76, 8.46, 15.0. (a) Explain why a graph of W against V² should be a straight line through the origin. (b) Calculate W/V² for the first and last readings. (c) Use the gradient to calculate the capacitance, in µF. Give only the answer to (c).', 2 * 15.0e-3 / 8.0 ** 2 * 1e6, 'µF',
  f'(a) W = ½CV², so W ∝ V² with gradient C/2. (b) 0.94 × 10⁻³ ÷ 2.0² = {sf(0.94e-3 / 4)} J V⁻² and 15.0 × 10⁻³ ÷ 8.0² = {sf(15e-3 / 64)} J V⁻², the same within experimental error. (c) C = 2 × gradient = 2 × {sf(15e-3 / 64, 4)} = {sf(2 * 15e-3 / 64)} F. In µF: {sf(2 * 15e-3 / 64, 4)} × 10⁶ = {sf(2 * 15e-3 / 64 * 1e6)}',
  ['M1: W = ½CV² so gradient C/2', 'C1: W/V² values', 'B1: constant within error', 'C1: C = 2 × gradient', 'C1: conversion to µF'], aq='C')
N('H', 6, 'An 80 pF parallel-plate capacitor (C = ε₀A/d) is charged to 250 V and disconnected. Its plates are then pulled apart until the separation is three times as large. (a) Calculate the initial energy stored. (b) Calculate the new capacitance and the new energy stored. (c) Calculate the work done in pulling the plates apart, in µJ. (d) Explain where this work comes from. Give only the answer to (c).', ((80e-12 * 250) ** 2 / (2 * 80e-12 / 3) - 0.5 * 80e-12 * 250 ** 2) * 1e6, 'µJ',
  f'(a) W₁ = 0.5 × 80 × 10⁻¹² × 250² = {sf(0.5 * 80e-12 * 250 ** 2)} J. (b) C₂ = 80 ÷ 3 = {sf(80 / 3)} pF. Q = 80 × 10⁻¹² × 250 = 2.0 × 10⁻⁸ C is unchanged, so W₂ = (2.0 × 10⁻⁸)² ÷ (2 × {sf(80e-12 / 3, 4)}) = {sf((2e-8) ** 2 / (2 * 80e-12 / 3))} J. (c) Work = {sf((2e-8) ** 2 / (2 * 80e-12 / 3), 4)} − {sf(0.5 * 80e-12 * 250 ** 2, 4)} = {sf((2e-8) ** 2 / (2 * 80e-12 / 3) - 0.5 * 80e-12 * 250 ** 2)} J. In µJ: {sf((2e-8) ** 2 / (2 * 80e-12 / 3) - 0.5 * 80e-12 * 250 ** 2, 4)} × 10⁶ = {sf(((2e-8) ** 2 / (2 * 80e-12 / 3) - 0.5 * 80e-12 * 250 ** 2) * 1e6)}. (d) The plates attract each other, so whoever pulls them apart does work against this force; that work becomes stored energy.',
  ['C1: initial ½CV²', 'C1: C ∝ 1/d', 'M1: Q constant so W = Q²/2C', 'C1: energy difference', 'B1: work against attraction of plates'], aq='W')
N('H', 6, 'A small electric car stores braking energy in a supercapacitor bank of 60 F that can be charged to 48 V. The car has a mass of 1200 kg. (a) Calculate the maximum energy the bank can store. (b) Calculate the highest speed from which the car could be braked to rest with all its kinetic energy stored in the bank. (c) Suggest one reason why, in practice, less energy is recovered. Give only the answer to (b).', sqrt(2 * 0.5 * 60 * 48 ** 2 / 1200), 'm s⁻¹',
  f'(a) W = 0.5 × 60 × 48² = {sf(0.5 * 60 * 48 ** 2)} J. (b) ½mv² = W, so v = √(2 × {sf(0.5 * 60 * 48 ** 2, 4)} ÷ 1200) = {sf(sqrt(2 * 0.5 * 60 * 48 ** 2 / 1200))} m s⁻¹. (c) Energy is lost as heat in the motor-generator, wiring and capacitor resistance, and some by friction in the brakes and tyres.',
  ['C1: W = ½CV²', 'M1: ½mv² = W', 'C1: rearranged for v', 'C1: substitution', 'B1: resistive or friction losses'], aq='v')
N('H', 5, 'A 470 µF capacitor charged to 12 V discharges until it has lost half of its stored energy. (a) Calculate the initial energy. (b) Calculate the p.d. when half the energy remains. (c) Calculate the charge that has flowed off the capacitor by then, in mC. Give only the answer to (c).', 470e-6 * (12 - 12 / sqrt(2)) * 1000, 'mC',
  f'(a) W = 0.5 × 470 × 10⁻⁶ × 12² = {sf(0.5 * 470e-6 * 144)} J. (b) W ∝ V², so V = 12 ÷ √2 = {sf(12 / sqrt(2))} V. (c) ΔQ = CΔV = 470 × 10⁻⁶ × (12 − {sf(12 / sqrt(2), 4)}) = {sf(470e-6 * (12 - 12 / sqrt(2)))} C. In mC: {sf(470e-6 * (12 - 12 / sqrt(2)), 4)} × 1000 = {sf(470e-6 * (12 - 12 / sqrt(2)) * 1000)}',
  ['C1: initial energy', 'M1: V ∝ √W', 'C1: ΔQ = CΔV', 'C1: conversion to mC'], aq='ΔQ')

# ═════════════════════════ 23.3 Capacitors in parallel (17/16/11) ═════════════════════════
lesson('23.3')
M('E', 1, 'Capacitors are connected in parallel across a supply. How is the total charge drawn from the supply related to the charges on the individual capacitors?', 'It is the sum of the individual charges', ['It equals the charge on the largest capacitor', 'It equals the charge on each capacitor', 'It is the average of the individual charges'], 'Each capacitor takes its own charge from the supply, so Q = Q₁ + Q₂ + …')
N('E', 2, 'A 220 µF capacitor and a 470 µF capacitor are connected in parallel. Calculate the combined capacitance in µF.', 220 + 470, 'µF',
  'C = C₁ + C₂ = 220 + 470 = 690 µF', ['C1: C = C₁ + C₂'], aq='C')
N('E', 2, 'Four 25 µF capacitors are connected in parallel. Calculate their combined capacitance in µF.', 4 * 25, 'µF',
  'Capacitances add in parallel: C = 4 × 25 = 100 µF', ['C1: capacitances add in parallel'], sig=2, aq='C')
M('E', 1, 'Which formula gives the total capacitance C of capacitors C₁, C₂ and C₃ connected in parallel?', 'C = C₁ + C₂ + C₃', ['1/C = 1/C₁ + 1/C₂ + 1/C₃', 'C = C₁C₂C₃', 'C = (C₁ + C₂ + C₃)/3'], 'In parallel the p.d. is common and the charges add, so the capacitances add.')
N('E', 2, 'Across a 9.0 V supply, a 33 µF capacitor sits alongside two other capacitors in parallel. Find the charge on the 33 µF capacitor, in µC.', 33 * 9.0, 'µC',
  'Each capacitor has the full 9.0 V across it: Q = CV = 33 × 10⁻⁶ × 9.0 = 2.97 × 10⁻⁴ C. In µC: 2.97 × 10⁻⁴ × 10⁶ = 297', ['C1: full supply p.d. across each'], aq='Q')
M('E', 1, 'Another capacitor is connected in parallel with a capacitor already across a battery. What happens to the total charge drawn from the battery?', 'It increases', ['It decreases', 'It stays the same', 'It becomes zero'], 'Total capacitance increases and V is fixed, so Q = CV increases.')
N('E', 2, 'A designer needs extra capacitance and wires two 47 µF capacitors alongside a 100 µF capacitor, all in parallel. What is the total, in µF?', 47 + 47 + 100, 'µF',
  'C = 47 + 47 + 100 = 194 µF', ['C1: sum of capacitances'], aq='C')
M('E', 1, 'In a parallel combination of different capacitors connected to a supply, which capacitor stores the most charge?', 'The one with the largest capacitance', ['The one with the smallest capacitance', 'They all store the same charge', 'The one nearest the supply'], 'They share the same p.d., so Q = CV is largest for the largest C.')
N('E', 2, 'Capacitors of 2.0 µF, 3.0 µF and 5.0 µF are connected in parallel across a 6.0 V supply. Calculate the total charge stored, in µC.', (2.0 + 3.0 + 5.0) * 6.0, 'µC',
  'C = 2.0 + 3.0 + 5.0 = 10 µF. Q = CV = 10 × 10⁻⁶ × 6.0 = 6.0 × 10⁻⁵ C. In µC: 6.0 × 10⁻⁵ × 10⁶ = 60', ['C1: total C then Q = CV'], sig=2, aq='Q')
M('E', 1, 'In a parallel combination, one capacitor is replaced by one of larger capacitance. What happens to the total capacitance?', 'It increases', ['It decreases', 'It stays the same', 'It becomes equal to the new capacitor'], 'C = C₁ + C₂ + …, so increasing any term increases the sum.')
N('E', 2, 'Two 100 µF capacitors are connected in parallel across 10 V. Calculate the total energy stored.', 0.5 * 200e-6 * 10 ** 2, 'J',
  'C = 200 µF. W = ½CV² = 0.5 × 200 × 10⁻⁶ × 10² = 0.010 J', ['C1: total C and W = ½CV²'], sig=2, aq='W')
M('E', 1, 'Two identical capacitors, each of capacitance C, are connected in parallel. What is the combined capacitance?', '2C', ['C/2', 'C', 'C²'], 'Capacitances add in parallel.')
N('E', 1, 'Calculate the total capacitance of a 1.0 µF capacitor and a 0.47 µF capacitor in parallel, in µF.', 1.0 + 0.47, 'µF',
  'C = 1.0 + 0.47 = 1.47 µF', [], aq='C')
M('E', 1, 'How does the total capacitance of a parallel combination compare with the largest capacitance in it?', 'It is greater than the largest capacitance', ['It is less than the smallest capacitance', 'It equals the largest capacitance', 'It equals the average capacitance'], 'Adding positive terms always gives a total bigger than any one term.')
N('E', 2, 'A 3.0 µF capacitor and a 7.0 µF capacitor are in parallel and together hold a total charge of 50 µC. Calculate the p.d. across them.', 50e-6 / 10e-6, 'V',
  'C = 3.0 + 7.0 = 10 µF. V = Q/C = 50 × 10⁻⁶ ÷ 10 × 10⁻⁶ = 5.0 V', ['C1: V = Q/C with total C'], sig=2, aq='V')
M('E', 1, 'Connecting two identical parallel-plate capacitors in parallel has the same effect as which change to one of them?', 'Doubling the area of its plates', ['Doubling the separation of its plates', 'Halving the area of its plates', 'Removing its dielectric'], 'C ∝ A: side-by-side plates act as one plate of twice the area.')
N('E', 2, 'A 10 µF capacitor and a 40 µF capacitor are connected in parallel to a supply. Calculate (charge on 10 µF) ÷ (charge on 40 µF).', 10 / 40, None,
  'Same p.d., so Q ∝ C: ratio = 10 ÷ 40 = 0.25', ['C1: Q ∝ C at the same V'], sig=2, aq='ratio')
# medium
N('M', 3, 'A smoothing bank is made of twelve 2200 µF capacitors in parallel, charged to 16 V. Calculate the total charge stored.', 12 * 2200e-6 * 16, 'C',
  f'C = 12 × 2200 × 10⁻⁶ = {sf(12 * 2200e-6)} F. Q = CV = {sf(12 * 2200e-6)} × 16 = {sf(12 * 2200e-6 * 16)} C', ['C1: total C = 12 × 2200 µF', 'C1: Q = CV'], aq='Q')
N('M', 3, 'Capacitors of 10 µF and 20 µF are in parallel across a 6.0 V supply. A 30 µF capacitor is then added in parallel. Calculate the extra charge drawn from the supply, in µC.', 30 * 6.0, 'µC',
  'Only the new capacitor needs charge, at the same 6.0 V: ΔQ = 30 × 10⁻⁶ × 6.0 = 1.8 × 10⁻⁴ C. In µC: 1.8 × 10⁻⁴ × 10⁶ = 180', ['C1: p.d. unchanged', 'C1: ΔQ = C_new × V'], sig=2, aq='ΔQ')
M('M', 3, 'Which statement is the key step in showing that capacitances add in parallel?', 'The p.d. is the same across each capacitor, so Q = Q₁ + Q₂ gives CV = C₁V + C₂V', ['The charge is the same on each capacitor, so the p.d.s add', 'The current is the same in each capacitor', 'The energy is the same in each capacitor'], 'Dividing CV = C₁V + C₂V by V gives C = C₁ + C₂.', ['C1: common V', 'C1: charges add'])
N('M', 4, 'A 20 µF capacitor charged to 9.0 V is disconnected from its supply and connected across an uncharged 10 µF capacitor. Calculate the final p.d. across the pair.', 20 * 9.0 / 30, 'V',
  'Charge is conserved: Q = 20 × 10⁻⁶ × 9.0 = 1.8 × 10⁻⁴ C. The pair is in parallel with C = 30 µF, so V = 1.8 × 10⁻⁴ ÷ 30 × 10⁻⁶ = 6.0 V', ['M1: total charge conserved', 'C1: capacitors in parallel, C = 30 µF', 'C1: V = Q/C'], sig=2, aq='V')
N('M', 3, 'A 20 µF capacitor charged to 9.0 V is connected across an uncharged 10 µF capacitor, and the common p.d. becomes 6.0 V. Calculate the final charge on the 10 µF capacitor, in µC.', 10 * 6.0, 'µC',
  'Q = CV = 10 × 10⁻⁶ × 6.0 = 6.0 × 10⁻⁵ C. In µC: 6.0 × 10⁻⁵ × 10⁶ = 60', ['C1: same p.d. across both', 'C1: Q = CV'], sig=2, aq='Q')
M('M', 3, 'A charged capacitor is connected across an uncharged one. Which statement about the total charge and the total energy is correct?', 'Total charge is unchanged but total energy decreases', ['Both are unchanged', 'Total charge decreases but total energy is unchanged', 'Both increase'], 'Charge is conserved; energy is lost as heat in the wires as charge flows between the capacitors.', ['C1: charge conserved', 'C1: energy dissipated'])
N('M', 3, 'A 47 µF capacitor and a 100 µF capacitor are connected in parallel across 12 V. Calculate the energy stored in the 47 µF capacitor, in mJ.', 0.5 * 47e-6 * 144 * 1000, 'mJ',
  f'Each capacitor has 12 V across it: W = 0.5 × 47 × 10⁻⁶ × 12² = {sf(0.5 * 47e-6 * 144)} J. In mJ: {sf(0.5 * 47e-6 * 144, 4)} × 1000 = {sf(0.5 * 47e-6 * 144 * 1000)}', ['C1: full p.d. across each', 'C1: W = ½CV²'], aq='W')
N('M', 3, 'A capacitor bank must store a charge of 0.50 C when charged to 25 V. Calculate the total capacitance needed, in µF.', 0.50 / 25 * 1e6, 'µF',
  'C = Q/V = 0.50 ÷ 25 = 0.020 F. In µF: 0.020 × 10⁶ = 20 000', ['C1: C = Q/V', 'C1: conversion to µF'], sig=2, aq='C')
M('M', 3, 'A tiny 1.0 µF capacitor is added in parallel with a large 100 µF one. What is the combined capacitance?', 'About 101 µF: the small capacitor makes little difference', ['About 1.0 µF', 'About 50 µF', 'About 0.99 µF'], 'C = 100 + 1.0 = 101 µF. About 0.99 µF would be the series value.', ['C1: C = C₁ + C₂', 'C1: series value is a distractor'])
N('M', 3, 'Capacitors of 22 µF, 47 µF and 33 µF are connected in parallel to a battery. Calculate the fraction of the total charge stored on the 22 µF capacitor.', 22 / (22 + 47 + 33), None,
  f'Q ∝ C at the same p.d., so fraction = 22 ÷ (22 + 47 + 33) = {sf(22 / 102)}', ['C1: Q ∝ C', 'C1: ÷ total C'], aq='fraction')
N('M', 3, 'Two capacitors in parallel across 12 V store charges of 120 µC and 360 µC. Calculate the total capacitance, in µF.', (120 + 360) / 12, 'µF',
  'Q = 120 + 360 = 480 µC. C = Q/V = 480 × 10⁻⁶ ÷ 12 = 4.0 × 10⁻⁵ F. In µF: 4.0 × 10⁻⁵ × 10⁶ = 40', ['C1: charges add', 'C1: C = Q/V'], sig=2, aq='C')
M('M', 4, 'A capacitor of capacitance C charged to p.d. V is connected across an identical uncharged capacitor. Which row describes the final state?', 'p.d. V/2; total energy half the original', ['p.d. V/2; total energy unchanged', 'p.d. V; total energy doubled', 'p.d. V/2; total energy one quarter of the original'], 'Q is shared over 2C, so V/2. W = ½(2C)(V/2)² = ¼CV², half of ½CV².', ['C1: charge conserved', 'C1: final V = V/2', 'C1: energy ¼CV²'])
N('M', 3, 'Three 4.7 µF capacitors are connected in parallel across a 9.0 V supply. Calculate the total energy stored, in mJ.', 0.5 * 3 * 4.7e-6 * 81 * 1000, 'mJ',
  f'C = 3 × 4.7 = 14.1 µF. W = 0.5 × 14.1 × 10⁻⁶ × 9.0² = {sf(0.5 * 14.1e-6 * 81)} J. In mJ: {sf(0.5 * 14.1e-6 * 81, 4)} × 1000 = {sf(0.5 * 14.1e-6 * 81 * 1000)}', ['C1: total C', 'C1: W = ½CV²'], aq='W')
N('M', 4, 'Five identical capacitors connected in parallel have a combined capacitance of 235 µF. Calculate the capacitance of one of them, in µF.', 235 / 5, 'µF',
  'C_total = 5C, so C = 235 ÷ 5 = 47 µF', ['M1: C_total = nC', 'C1: rearranged', 'C1: value'], sig=2, aq='C')
M('M', 3, 'A 25 V-rated capacitor and a 16 V-rated capacitor are connected in parallel. What is the largest p.d. that can safely be applied to the combination?', '16 V', ['25 V', '41 V', '20.5 V'], 'Both capacitors get the full p.d., so it must not exceed the lower rating.', ['C1: same p.d. across each', 'C1: limited by lower rating'])
N('M', 3, 'A parallel pair of capacitors stores 0.18 J at 30 V. One of them is 150 µF. Calculate the capacitance of the other, in µF.', 2 * 0.18 / 30 ** 2 * 1e6 - 150, 'µF',
  'C_total = 2W/V² = 2 × 0.18 ÷ 30² = 4.0 × 10⁻⁴ F, which is 400 µF. Other = 400 − 150 = 250 µF', ['C1: C = 2W/V²', 'C1: subtract'], sig=2, aq='C')
# hard
N('H', 6, 'A 470 µF capacitor is charged to 12 V and then connected across an uncharged 220 µF capacitor. (a) Calculate the charge on the 470 µF capacitor before connection. (b) Calculate the common p.d. after connection. (c) Show that the fraction of the original energy that remains is 470/690. (d) Calculate the percentage of the original energy that is lost. Give only the answer to (d), in %.', (1 - 470 / 690) * 100, '%',
  f'(a) Q = 470 × 10⁻⁶ × 12 = {sf(470e-6 * 12)} C. (b) V = {sf(470e-6 * 12, 4)} ÷ 690 × 10⁻⁶ = {sf(470 * 12 / 690)} V. (c) W₂/W₁ = (Q²/2C₂) ÷ (Q²/2C₁) = C₁/C₂ = 470/690. (d) Loss = (1 − 470 ÷ 690) × 100 = {sf((1 - 470 / 690) * 100)} %',
  ['C1: Q = CV', 'C1: V = Q/(C₁ + C₂)', 'M1: W = Q²/2C with Q fixed', 'B1: ratio C₁/C₂ shown', 'C1: percentage lost'], aq='percentage')
N('H', 5, 'A 10 µF capacitor C₁ is charged to 12 V and connected across an uncharged 20 µF capacitor C₂. C₂ is then disconnected and connected across an uncharged 20 µF capacitor C₃. (a) Calculate the p.d. across C₁ and C₂ after the first connection. (b) Calculate the charge on C₂ after the first connection. (c) Calculate the final charge on C₃, in µC. Give only the answer to (c).', 20 * (20 * 4.0) / 40, 'µC',
  '(a) Q = 10 × 10⁻⁶ × 12 = 1.2 × 10⁻⁴ C shared over 30 µF: V = 1.2 × 10⁻⁴ ÷ 30 × 10⁻⁶ = 4.0 V. (b) Q₂ = 20 × 10⁻⁶ × 4.0 = 8.0 × 10⁻⁵ C. (c) C₂ and C₃ share 8.0 × 10⁻⁵ C over 40 µF: V = 8.0 × 10⁻⁵ ÷ 40 × 10⁻⁶ = 2.0 V, so Q₃ = 20 × 10⁻⁶ × 2.0 = 4.0 × 10⁻⁵ C. In µC: 4.0 × 10⁻⁵ × 10⁶ = 40',
  ['M1: charge conserved at each step', 'C1: V = 4.0 V', 'C1: Q₂', 'C1: second sharing'], sig=2, aq='Q₃')
N('H', 6, 'A student connects increasing numbers n of nominally identical capacitors in parallel and measures the total capacitance: n = 1, 2, 3, 4 and C/µF = 4.6, 9.5, 14.0, 18.9. (a) Explain why a graph of C against n should be a straight line through the origin. (b) Calculate the gradient using the first and last readings. (c) State the mean capacitance of one capacitor, in µF. (d) Suggest why the individual readings do not lie exactly on the line. Give only the answer to (c).', (18.9 - 4.6) / 3, 'µF',
  f'(a) C_total = nC, so C ∝ n with gradient C. (b) Gradient = (18.9 − 4.6) ÷ (4 − 1) = {sf(14.3 / 3)} µF. (c) Mean capacitance = gradient = {sf(14.3 / 3)} µF. (d) The capacitors have a manufacturing tolerance (often ±10 %), and the meter and leads add small errors.',
  ['B1: C_total = nC', 'C1: gradient', 'M1: gradient = C of one', 'B1: tolerance or stray capacitance', 'C1: value'], aq='C')
N('H', 5, 'A power supply needs a smoothing capacitance of at least 10 000 µF that can work at 30 V. Only 2200 µF capacitors rated at 50 V are available. (a) Calculate the minimum number of capacitors needed and state how they must be connected. (b) Calculate the energy stored by this arrangement at 30 V. Give only the answer to (b).', 0.5 * 5 * 2200e-6 * 30 ** 2, 'J',
  f'(a) 10 000 ÷ 2200 = {sf(10000 / 2200)}, so 5 capacitors in parallel (11 000 µF); parallel keeps each at 30 V, within its 50 V rating. (b) W = 0.5 × 5 × 2200 × 10⁻⁶ × 30² = {sf(0.5 * 11000e-6 * 900)} J',
  ['C1: 10 000 ÷ 2200', 'B1: 5 in parallel', 'B1: within voltage rating', 'C1: W = ½CV²'], aq='W')
N('H', 6, 'A 20 µF capacitor charged to 10 V and a 30 µF capacitor charged to 5.0 V are joined, positive plate to positive plate. (a) Calculate the total charge. (b) Calculate the final common p.d. (c) Calculate the energy lost, in mJ. (d) Calculate the final p.d. if instead the positive plate of each were joined to the negative plate of the other. Give only the answer to (b).', (20 * 10 + 30 * 5.0) / 50, 'V',
  f'(a) Q = 20 × 10⁻⁶ × 10 + 30 × 10⁻⁶ × 5.0 = 3.5 × 10⁻⁴ C. (b) V = 3.5 × 10⁻⁴ ÷ 50 × 10⁻⁶ = 7.0 V. (c) Before: 0.5 × 20 × 10⁻⁶ × 10² + 0.5 × 30 × 10⁻⁶ × 5.0² = {sf(0.5 * 20e-6 * 100 + 0.5 * 30e-6 * 25)} J; after: 0.5 × 50 × 10⁻⁶ × 7.0² = {sf(0.5 * 50e-6 * 49)} J; loss = {sf(0.5 * 20e-6 * 100 + 0.5 * 30e-6 * 25 - 0.5 * 50e-6 * 49)} J, which is 0.150 mJ. (d) Charges partly cancel: V = (20 × 10 − 30 × 5.0) ÷ 50 = 1.0 V.',
  ['C1: total charge', 'M1: V = Q_total/C_total', 'C1: energy before and after', 'C1: energy lost', 'B1: opposite connection gives 1.0 V'], sig=2, aq='V')
N('H', 5, '(a) Show that three capacitors in parallel have a total capacitance C = C₁ + C₂ + C₃. (b) Capacitors of 2.2 µF, 4.7 µF and 10 µF are connected in parallel across a 15 V supply. Calculate the total capacitance and the total charge, in µC. Give only the total charge.', (2.2 + 4.7 + 10) * 15, 'µC',
  '(a) Each has the same p.d. V; total charge Q = C₁V + C₂V + C₃V = (C₁ + C₂ + C₃)V, and C = Q/V. (b) C = 2.2 + 4.7 + 10 = 16.9 µF. Q = 16.9 × 10⁻⁶ × 15 = 2.535 × 10⁻⁴ C. In µC: 2.535 × 10⁻⁴ × 10⁶ = 254',
  ['M1: same p.d., charges add', 'B1: C = C₁ + C₂ + C₃', 'C1: total C', 'C1: Q = CV'], aq='Q')
N('H', 6, 'A touch-screen sensor pad has a capacitance of 15 pF. A finger close to the pad adds 10 pF in parallel. The circuit charges the pad to 3.3 V and then discharges it 1000 times per second. (a) Calculate the charge on the pad with no finger present. (b) Calculate the extra charge per cycle when a finger is present. (c) Calculate the change in the average current, in nA. (d) Explain how the circuit detects a touch. Give only the answer to (c).', 10e-12 * 3.3 * 1000 * 1e9, 'nA',
  '(a) Q = 15 × 10⁻¹² × 3.3 = 4.95 × 10⁻¹¹ C. (b) ΔQ = 10 × 10⁻¹² × 3.3 = 3.3 × 10⁻¹¹ C. (c) ΔI = ΔQ × 1000 = 3.3 × 10⁻¹¹ × 1000 = 3.3 × 10⁻⁸ A. In nA: 3.3 × 10⁻⁸ × 10⁹ = 33. (d) The extra parallel capacitance means more charge flows each cycle, so the average current rises; the circuit senses this rise.',
  ['C1: Q = CV', 'M1: parallel capacitances add', 'C1: I = Q × frequency', 'C1: conversion to nA', 'B1: increase in current detected'], sig=2, aq='ΔI')
N('H', 5, 'A 10 µF and a 40 µF capacitor are connected in parallel across a 20 V supply. (a) Calculate the energy stored in each. (b) Calculate the fraction of the total energy stored in the 10 µF capacitor. (c) State and explain how this fraction would change if the two capacitors were connected in series instead. Give only the answer to (b).', 10 / 50, None,
  '(a) W₁₀ = 0.5 × 10 × 10⁻⁶ × 20² = 2.0 × 10⁻³ J; W₄₀ = 0.5 × 40 × 10⁻⁶ × 20² = 8.0 × 10⁻³ J. (b) Fraction = 2.0 × 10⁻³ ÷ (2.0 × 10⁻³ + 8.0 × 10⁻³) = 0.20. (c) In series both carry the same charge, and W = Q²/2C, so the 10 µF capacitor would store four times as much as the 40 µF one: its fraction would rise to 0.80.',
  ['C1: W = ½CV² for each', 'C1: fraction', 'M1: in series same Q', 'B1: W ∝ 1/C so fraction 0.80'], sig=2, aq='fraction')
N('H', 6, 'A 100 µF capacitor charged to 20 V is connected across an identical uncharged capacitor, which is then disconnected and discharged. This is repeated. (a) Show that after n connections the p.d. on the first capacitor is 20/2ⁿ V. (b) Calculate the p.d. after 3 connections. (c) Find the smallest number of connections after which the energy stored is less than 1 % of its original value. Give only the answer to (b).', 20 / 2 ** 3, 'V',
  '(a) Each connection shares the charge equally between two identical capacitors, halving Q and therefore V. (b) V = 20 ÷ 2³ = 2.5 V. (c) W ∝ V², so W falls by a factor of 4 each time. After 3 connections the energy is 1/64 of the original, about 1.6 %; after 4 it is 1/256, about 0.39 %, so 4 connections.',
  ['M1: charge halves each time', 'C1: 20/2³', 'M1: W ∝ V², factor 4', 'C1: 1/64 > 1 %', 'A1: 4 connections'], sig=2, aq='V')
N('H', 5, 'A pulsed laser is powered by 40 capacitors, each of 50 µF, connected in parallel and charged to 2.0 kV. (a) Calculate the total capacitance. (b) Calculate the energy stored. (c) The bank discharges in 1.0 ms. Calculate the average power, in MW. Give only the answer to (b).', 0.5 * 40 * 50e-6 * 2.0e3 ** 2, 'J',
  '(a) C = 40 × 50 = 2000 µF. (b) W = 0.5 × 2000 × 10⁻⁶ × (2.0 × 10³)² = 4000 J. (c) P = 4000 ÷ 1.0 × 10⁻³ = 4.0 × 10⁶ W, which is 4.0 MW.',
  ['C1: parallel capacitances add', 'C1: W = ½CV²', 'C1: P = W/t', 'B1: MW conversion'], sig=2, aq='W')
N('H', 6, 'To measure an unknown capacitance C, a 470 µF capacitor is charged to 9.0 V and then connected across the unknown, uncharged capacitor. A voltmeter of very high resistance then reads 6.3 V. (a) Calculate the initial charge. (b) Calculate C, in µF. (c) Explain why the voltmeter must have a very high resistance. Give only the answer to (b).', 470 * (9.0 - 6.3) / 6.3, 'µF',
  f'(a) Q = 470 × 10⁻⁶ × 9.0 = {sf(470e-6 * 9)} C. (b) Charge conserved: (470 + C) × 6.3 = 470 × 9.0, so C = 470 × (9.0 − 6.3) ÷ 6.3 = {sf(470 * 2.7 / 6.3)} µF. (c) A low-resistance meter would let charge flow through it, discharging the capacitors and making the reading fall.',
  ['C1: Q = CV', 'M1: charge conserved in parallel', 'C1: rearranged for C', 'C1: value', 'B1: meter must not discharge capacitors'], aq='C')

# ═════════════════════════ 23.4 Capacitors in series (17/17/10) ═════════════════════════
lesson('23.4')
M('E', 1, 'Capacitors are connected in series to a battery. Which quantity is the same for every capacitor?', 'The charge on each capacitor', ['The p.d. across each capacitor', 'The energy stored in each capacitor', 'The capacitance of each capacitor'], 'The battery moves charge Q onto the end plates; each inner pair of plates gets ±Q by electron transfer.')
M('E', 1, 'Which formula gives the total capacitance C of C₁ and C₂ in series?', '1/C = 1/C₁ + 1/C₂', ['C = C₁ + C₂', 'C = 1/C₁ + 1/C₂', 'C = C₁ − C₂'], 'The p.d.s add and the charge is common: V/Q = V₁/Q + V₂/Q.')
N('E', 2, 'A 10 µF capacitor and a 15 µF capacitor are connected in series. Calculate the combined capacitance in µF.', ser(10, 15), 'µF',
  '1/C = 1/10 + 1/15, so C = 10 × 15 ÷ (10 + 15) = 6.0 µF', ['C1: product over sum'], sig=2, aq='C')
N('E', 2, 'Two 470 µF capacitors are connected in series. Calculate the combined capacitance in µF.', 470 / 2, 'µF',
  'Two equal capacitors in series give half: C = 470 ÷ 2 = 235 µF', ['C1: 1/C = 2/470'], aq='C')
M('E', 1, 'How does the combined capacitance of capacitors in series compare with the smallest capacitance in the chain?', 'It is less than the smallest', ['It is greater than the largest', 'It equals the smallest', 'It equals the average'], 'Adding reciprocals makes 1/C larger than any single 1/Cₙ.')
N('E', 2, 'Two 2.0 µF capacitors in series are connected across a 12 V supply. Calculate the p.d. across each capacitor.', 12 / 2, 'V',
  'They are identical and carry the same charge, so the p.d. divides equally: 12 ÷ 2 = 6.0 V', ['C1: equal share for equal C'], sig=2, aq='V')
M('E', 1, 'Two different capacitors in series are connected to a supply. Which capacitor has the larger p.d. across it?', 'The one with the smaller capacitance', ['The one with the larger capacitance', 'They have equal p.d.s', 'The one nearer the positive terminal'], 'Same Q, so V = Q/C is larger for smaller C.')
N('E', 2, 'Calculate the combined capacitance of a 20 µF and a 5.0 µF capacitor in series, in µF.', ser(20, 5.0), 'µF',
  'C = 20 × 5.0 ÷ (20 + 5.0) = 4.0 µF', ['C1: product over sum'], sig=2, aq='C')
N('E', 2, 'Several capacitors in series behave as a single 3.0 µF capacitor. When 10 V is applied across the chain, what charge sits on each capacitor, in µC?', 3.0 * 10, 'µC',
  'Q = CV = 3.0 × 10⁻⁶ × 10 = 3.0 × 10⁻⁵ C. In µC: 3.0 × 10⁻⁵ × 10⁶ = 30', ['C1: Q = C_total V'], sig=2, aq='Q')
M('E', 1, 'For capacitors in series across a supply, how are the individual p.d.s related to the supply p.d.?', 'They add up to the supply p.d.', ['Each equals the supply p.d.', 'They are all equal to zero', 'They multiply to give the supply p.d.'], 'By energy conservation (Kirchhoff\'s second law), the p.d.s around a series chain sum to the e.m.f.')
N('E', 2, 'A chain of four identical 100 µF capacitors is wired end to end. What single capacitance, in µF, could replace the chain?', 100 / 4, 'µF',
  '1/C = 4/100, so C = 100 ÷ 4 = 25 µF', ['C1: n equal capacitors give C/n'], sig=2, aq='C')
M('E', 1, 'Why might capacitors be connected in series in a high-voltage circuit?', 'So that the supply p.d. is shared, and no single capacitor exceeds its voltage rating', ['To increase the total capacitance', 'To increase the charge stored', 'To make the current larger'], 'In series each capacitor has only part of the total p.d.')
N('E', 1, 'Two identical capacitors in series have a combined capacitance of 50 µF. What is the capacitance of each, in µF?', 100, 'µF',
  'C_series = C/2, so C = 2 × 50 = 100 µF', [], sig=2, aq='C')
N('E', 2, 'Three 1.0 µF capacitors are connected in series across a 9.0 V supply. Calculate the p.d. across each.', 9.0 / 3, 'V',
  'Identical capacitors share the p.d. equally: 9.0 ÷ 3 = 3.0 V', ['C1: equal share'], sig=2, aq='V')
M('E', 1, 'How do the inner plates of two capacitors in series become charged, even though they are not connected to the supply?', 'Electrons move along the wire between them, leaving one plate positive and the other negative', ['Charge jumps across the dielectric', 'The supply connects to them through the dielectric', 'They do not become charged'], 'The charge on the outer plates attracts or repels electrons in the isolated middle section.')
N('E', 2, 'Find the effective capacitance, in µF, when a 3.3 µF capacitor is placed in series with a 6.8 µF one.', ser(6.8, 3.3), 'µF',
  f'C = 6.8 × 3.3 ÷ (6.8 + 3.3) = {sf(6.8 * 3.3 / 10.1)} µF', ['C1: product over sum'], aq='C')
M('E', 1, 'A third capacitor is added in series to two capacitors already in series. What happens to the total capacitance?', 'It decreases', ['It increases', 'It stays the same', 'It doubles'], 'Another positive term is added to 1/C, so C falls.')
# medium
N('M', 3, 'A 4.0 µF and a 6.0 µF capacitor are connected in series across a 20 V supply. Calculate the charge on each capacitor, in µC.', ser(4.0, 6.0) * 20, 'µC',
  'C = 4.0 × 6.0 ÷ (4.0 + 6.0) = 2.4 µF. Q = 2.4 × 10⁻⁶ × 20 = 4.8 × 10⁻⁵ C. In µC: 4.8 × 10⁻⁵ × 10⁶ = 48', ['C1: series C', 'C1: Q = CV'], sig=2, aq='Q')
N('M', 3, 'A 4.0 µF and a 6.0 µF capacitor in series across 20 V each carry 48 µC. Calculate the p.d. across the 4.0 µF capacitor.', 48 / 4.0, 'V',
  'V = Q/C = 48 × 10⁻⁶ ÷ 4.0 × 10⁻⁶ = 12 V', ['C1: same Q on each', 'C1: V = Q/C'], sig=2, aq='V')
N('M', 4, 'Capacitors of 2.0 µF, 3.0 µF and 6.0 µF are connected in series across a 12 V supply. Calculate the p.d. across the 2.0 µF capacitor.', ser(2.0, 3.0, 6.0) * 12 / 2.0, 'V',
  '1/C = 1/2.0 + 1/3.0 + 1/6.0 = 1.0, so C = 1.0 µF. Q = 1.0 × 10⁻⁶ × 12 = 1.2 × 10⁻⁵ C. V = 1.2 × 10⁻⁵ ÷ 2.0 × 10⁻⁶ = 6.0 V', ['C1: series C', 'C1: Q = CV', 'C1: V = Q/C'], sig=2, aq='V')
M('M', 3, 'A 1.0 µF and a 3.0 µF capacitor are connected in series across a supply. What is (p.d. across 1.0 µF) ÷ (p.d. across 3.0 µF)?', '3', ['1/3', '1', '9'], 'Same Q, so V ∝ 1/C: the smaller capacitor takes three times the p.d.', ['C1: same Q', 'C1: V ∝ 1/C'])
N('M', 3, 'Two 100 µF capacitors in series are charged to a total p.d. of 50 V. Calculate the total energy stored, in mJ.', 0.5 * 50e-6 * 50 ** 2 * 1000, 'mJ',
  f'C = 100 ÷ 2 = 50 µF. W = 0.5 × 50 × 10⁻⁶ × 50² = {sf(0.5 * 50e-6 * 2500)} J. In mJ: {sf(0.5 * 50e-6 * 2500)} × 1000 = {sf(0.5 * 50e-6 * 2500 * 1000)}', ['C1: series C', 'C1: W = ½CV²'], aq='W')
N('M', 3, 'A 12 µF capacitor is connected in series with an unknown capacitor, giving a combined capacitance of 4.0 µF. Calculate the unknown capacitance, in µF.', 1 / (1 / 4.0 - 1 / 12), 'µF',
  '1/C_x = 1/4.0 − 1/12 = 1/6.0, so C_x = 1 ÷ (1/4.0 − 1/12) = 6.0 µF', ['M1: 1/C_x = 1/C − 1/C₁', 'C1: value'], sig=2, aq='C')
M('M', 4, 'Two 100 µF capacitors, each rated at 16 V, are connected in series. Which row gives the combination\'s capacitance and maximum safe p.d.?', '50 µF and 32 V', ['200 µF and 16 V', '50 µF and 16 V', '200 µF and 32 V'], 'Series halves C; each takes half the p.d., so the pair can take 2 × 16 V.', ['C1: series C = 50 µF', 'C1: p.d. shared equally', 'C1: 32 V'])
N('M', 3, 'A 2.0 µF and an 8.0 µF capacitor are in series across a 10 V supply. Calculate the energy stored in the 2.0 µF capacitor, in µJ.', (ser(2.0e-6, 8.0e-6) * 10) ** 2 / (2 * 2.0e-6) * 1e6, 'µJ',
  f'C = 2.0 × 8.0 ÷ 10 = 1.6 µF. Q = 1.6 × 10⁻⁶ × 10 = 1.6 × 10⁻⁵ C. W = Q²/2C = (1.6 × 10⁻⁵)² ÷ (2 × 2.0 × 10⁻⁶) = {sf((1.6e-5) ** 2 / 4e-6)} J. In µJ: {sf((1.6e-5) ** 2 / 4e-6)} × 10⁶ = {sf((1.6e-5) ** 2 / 4e-6 * 1e6)}', ['C1: series C and Q', 'C1: W = Q²/2C'], aq='W')
N('M', 3, 'A 22 µF and a 47 µF capacitor in series are connected across 9.0 V. Calculate the charge on each, in µC.', ser(22, 47) * 9.0, 'µC',
  f'C = 22 × 47 ÷ (22 + 47) = {sf(22 * 47 / 69)} µF. Q = {sf(22 * 47 / 69, 4)} × 9.0 = {sf(22 * 47 / 69 * 9)} µC', ['C1: series C', 'C1: Q = CV'], aq='Q')
M('M', 3, 'In a series pair, one capacitor is replaced by one of very much larger capacitance. What does the combined capacitance approach?', 'The capacitance of the other (smaller) capacitor', ['The capacitance of the very large capacitor', 'Zero', 'The sum of the two capacitances'], '1/C = 1/C₁ + 1/C₂ → 1/C₁ as C₂ → ∞.', ['C1: 1/C₂ → 0', 'C1: C → C₁'])
N('M', 4, 'Three identical 0.30 µF capacitors, each rated at 2.0 kV, are connected in series across a 5.0 kV supply. Calculate the charge on each capacitor, in mC.', 0.10e-6 * 5.0e3 * 1000, 'mC',
  'C = 0.30 ÷ 3 = 0.10 µF. Q = 0.10 × 10⁻⁶ × 5.0 × 10³ = 5.0 × 10⁻⁴ C. In mC: 5.0 × 10⁻⁴ × 1000 = 0.50. Each has 5.0 ÷ 3 = 1.67 kV, within its rating.', ['C1: series C', 'C1: Q = CV', 'C1: conversion to mC'], sig=2, aq='Q')
N('M', 3, 'How many 10 µF capacitors must be connected in series to give a combined capacitance of 2.5 µF?', 10 / 2.5, None,
  'n equal capacitors in series give C/n, so n = 10 ÷ 2.5 = 4', ['C1: C_total = C/n', 'C1: rearranged'], sig=1, aq='n')
M('M', 3, 'Why do all capacitors in a series chain carry the same charge?', 'Each isolated section between capacitors is neutral overall, so it gains +Q on one plate exactly as it loses −Q from the other', ['The supply forces the same p.d. across each', 'Charge flows through the dielectrics', 'All the capacitors have the same capacitance'], 'Charge conservation in each isolated conductor between capacitors gives equal and opposite charges.', ['C1: isolated sections', 'C1: charge conservation'])
N('M', 3, 'A 0.10 µF capacitor is connected in series with a 100 µF capacitor. Calculate the combined capacitance, in µF.', ser(0.10, 100), 'µF',
  f'C = 0.10 × 100 ÷ (0.10 + 100) = {sf(10 / 100.1)} µF: almost exactly the smaller value', ['C1: product over sum', 'C1: dominated by the smaller C'], aq='C')
N('M', 4, 'A 10 µF and a 40 µF capacitor are connected in series across 25 V. Calculate the p.d. across the 10 µF capacitor.', 25 * 40 / 50, 'V',
  'Same Q, so V ∝ 1/C and the p.d.s are in the ratio 40 : 10. V₁₀ = 25 × 40 ÷ (10 + 40) = 20 V', ['C1: same Q', 'M1: V ∝ 1/C', 'C1: share of 25 V'], sig=2, aq='V')
M('M', 3, 'Two identical capacitors are connected first in parallel and then in series. What is (capacitance in parallel) ÷ (capacitance in series)?', '4', ['2', '1', '½'], 'Parallel: 2C. Series: C/2. Ratio = 4.', ['C1: parallel 2C', 'C1: series C/2'])
N('M', 3, 'A 3.3 µF and a 6.8 µF capacitor in series are charged by a 15 V supply. Calculate the total energy stored, in mJ.', 0.5 * ser(3.3e-6, 6.8e-6) * 15 ** 2 * 1000, 'mJ',
  f'C = 3.3 × 6.8 ÷ 10.1 = {sf(3.3 * 6.8 / 10.1)} µF. W = 0.5 × {sf(3.3 * 6.8 / 10.1, 4)} × 10⁻⁶ × 15² = {sf(0.5 * 3.3 * 6.8 / 10.1 * 1e-6 * 225)} J. In mJ: {sf(0.5 * 3.3 * 6.8 / 10.1 * 1e-6 * 225, 4)} × 1000 = {sf(0.5 * 3.3 * 6.8 / 10.1 * 1e-6 * 225 * 1000)}', ['C1: series C', 'C1: W = ½CV²'], aq='W')
# hard
N('H', 6, '(a) Show that three capacitors in series have a combined capacitance given by 1/C = 1/C₁ + 1/C₂ + 1/C₃. (b) Capacitors of 4.7 µF, 10 µF and 22 µF are connected in series across 30 V. Calculate the combined capacitance. (c) Calculate the charge on each capacitor. (d) Calculate the p.d. across the 4.7 µF capacitor. Give only the answer to (d).', ser(4.7, 10, 22) * 30 / 4.7, 'V',
  f'(a) Each capacitor carries Q and V = V₁ + V₂ + V₃, so Q/C = Q/C₁ + Q/C₂ + Q/C₃; dividing by Q gives the result. (b) 1/C = 1/4.7 + 1/10 + 1/22 = {sf(1 / 4.7 + 0.1 + 1 / 22, 4)}, so C = {sf(ser(4.7, 10, 22))} µF. (c) Q = {sf(ser(4.7, 10, 22), 4)} × 30 = {sf(ser(4.7, 10, 22) * 30)} µC. (d) V = {sf(ser(4.7, 10, 22) * 30, 4)} ÷ 4.7 = {sf(ser(4.7, 10, 22) * 30 / 4.7)} V',
  ['M1: same Q, p.d.s add', 'B1: reciprocal rule derived', 'C1: series C', 'C1: Q = CV', 'C1: V = Q/C'], aq='V')
N('H', 5, 'A capacitive voltage divider uses a 100 pF capacitor in series with a 900 pF capacitor across a 1000 V source. (a) Explain why the charge on each capacitor is the same. (b) Calculate the combined capacitance. (c) Calculate the p.d. across the 900 pF capacitor. Give only the answer to (c).', 1000 * 100 / 1000, 'V',
  '(a) The middle conductor is isolated, so it gains equal and opposite charges. (b) C = 100 × 900 ÷ 1000 = 90 pF. (c) Q = 90 × 10⁻¹² × 1000 = 9.0 × 10⁻⁸ C. V = 9.0 × 10⁻⁸ ÷ 900 × 10⁻¹² = 100 V',
  ['B1: isolated middle conductor', 'C1: series C', 'C1: Q = CV', 'C1: V = Q/C'], sig=2, aq='V')
N('H', 6, 'A 2.0 µF capacitor and a 3.0 µF capacitor are each rated at 50 V. They are connected in series. (a) Explain which capacitor has the larger p.d. across it. (b) Find the fraction of the supply p.d. across the 2.0 µF capacitor. (c) Calculate the largest supply p.d. that can be used without exceeding either rating. Give only the answer to (c).', 50 / (3.0 / 5.0), 'V',
  f'(a) The 2.0 µF capacitor: same charge, so V = Q/C is larger for smaller C. (b) V ∝ 1/C, so the fraction = 3.0 ÷ (2.0 + 3.0) = 0.60. (c) The 2.0 µF capacitor reaches 50 V first: V_supply = 50 ÷ 0.60 = {sf(50 / 0.6)} V',
  ['B1: smaller C has larger V', 'M1: V ∝ 1/C', 'C1: fraction 0.60', 'C1: limit set by the 2.0 µF capacitor', 'C1: substitution'], aq='V')
N('H', 6, 'A 4.0 µF and a 12 µF capacitor are connected in series across a 16 V supply. (a) Calculate the combined capacitance. (b) Calculate the charge on each. (c) Calculate the energy stored in each capacitor. (d) Show that the total equals the energy stored in the combined capacitance. Give only the energy in the 4.0 µF capacitor, in mJ.', (ser(4e-6, 12e-6) * 16) ** 2 / (2 * 4e-6) * 1000, 'mJ',
  f'(a) C = 4.0 × 12 ÷ 16 = 3.0 µF. (b) Q = 3.0 × 10⁻⁶ × 16 = 4.8 × 10⁻⁵ C. (c) W₄ = (4.8 × 10⁻⁵)² ÷ (2 × 4.0 × 10⁻⁶) = {sf((4.8e-5) ** 2 / 8e-6)} J. In mJ: {sf((4.8e-5) ** 2 / 8e-6)} × 1000 = {sf((4.8e-5) ** 2 / 8e-6 * 1000)}. W₁₂ = (4.8 × 10⁻⁵)² ÷ (2 × 12 × 10⁻⁶) = {sf((4.8e-5) ** 2 / 24e-6)} J. (d) Total = {sf((4.8e-5) ** 2 / 8e-6 + (4.8e-5) ** 2 / 24e-6)} J, and 0.5 × 3.0 × 10⁻⁶ × 16² = {sf(0.5 * 3e-6 * 256)} J, the same.',
  ['C1: series C', 'C1: Q = CV', 'M1: W = Q²/2C for each', 'C1: values', 'B1: totals agree'], aq='W')
N('H', 6, 'A 2.0 µF and a 6.0 µF capacitor are connected in series across a 12 V supply. They are then disconnected from the supply and from each other, and reconnected in parallel, positive plate to positive plate. (a) Calculate the charge on each capacitor while in series. (b) Calculate the total charge after reconnection. (c) Calculate the final p.d. across the parallel pair. Give only the answer to (c).', 2 * ser(2.0, 6.0) * 12 / 8.0, 'V',
  '(a) C = 2.0 × 6.0 ÷ 8.0 = 1.5 µF; Q = 1.5 × 10⁻⁶ × 12 = 1.8 × 10⁻⁵ C on each. (b) Positive plates joined: total Q = 2 × 1.8 × 10⁻⁵ = 3.6 × 10⁻⁵ C. (c) In parallel C = 8.0 µF, so V = 3.6 × 10⁻⁵ ÷ 8.0 × 10⁻⁶ = 4.5 V',
  ['C1: series C', 'C1: same Q on each', 'M1: charges add when like plates joined', 'C1: parallel C', 'C1: V = Q/C'], sig=2, aq='V')
N('H', 5, 'Three 6.0 µF capacitors are connected in series across an 18 V supply. One of them breaks down and becomes a short circuit. (a) Calculate the p.d. across each capacitor before the fault. (b) Calculate the combined capacitance after the fault. (c) Calculate the p.d. across each of the remaining capacitors. Give only the answer to (c).', 18 / 2, 'V',
  '(a) Identical, so 18 ÷ 3 = 6.0 V each. (b) Two 6.0 µF in series: C = 6.0 ÷ 2 = 3.0 µF. (c) The 18 V is now shared by two: 18 ÷ 2 = 9.0 V each, which may exceed their rating.',
  ['C1: equal share before', 'C1: series C of two', 'M1: supply p.d. shared by two', 'B1: risk of further breakdown'], sig=2, aq='V')
N('H', 6, 'A student connects n identical capacitors in series and measures the combined capacitance C. Values of 1/C are: n = 1, 2, 3, 4 and (1/C)/µF⁻¹ = 0.213, 0.426, 0.638, 0.851. (a) Explain why a graph of 1/C against n is a straight line through the origin. (b) Calculate the gradient using the first and last readings. (c) Calculate the capacitance of one capacitor, in µF. Give only the answer to (c).', 3 / (0.851 - 0.213), 'µF',
  f'(a) 1/C = n/C₁, so 1/C ∝ n with gradient 1/C₁. (b) Gradient = (0.851 − 0.213) ÷ (4 − 1) = {sf(0.638 / 3)} µF⁻¹. (c) C₁ = 1 ÷ {sf(0.638 / 3, 4)} = {sf(3 / 0.638)} µF',
  ['M1: 1/C = n/C₁', 'B1: straight line through origin', 'C1: gradient', 'C1: C₁ = 1/gradient', 'C1: value'], aq='C')
N('H', 5, 'An unknown capacitor is connected in series with a 10 µF capacitor across a 12 V supply. A high-resistance voltmeter shows 8.0 V across the 10 µF capacitor. (a) Calculate the charge on the 10 µF capacitor. (b) State the p.d. across the unknown capacitor. (c) Calculate the unknown capacitance, in µF. Give only the answer to (c).', 80 / 4.0, 'µF',
  '(a) Q = 10 × 10⁻⁶ × 8.0 = 8.0 × 10⁻⁵ C. (b) 12 − 8.0 = 4.0 V. (c) Same charge in series: C = 8.0 × 10⁻⁵ ÷ 4.0 = 2.0 × 10⁻⁵ F. In µF: 2.0 × 10⁻⁵ × 10⁶ = 20',
  ['C1: Q = CV', 'C1: p.d.s add to 12 V', 'M1: same Q', 'C1: C = Q/V'], sig=2, aq='C')
N('H', 6, 'Three identical 3.3 µF capacitors are connected in series across a 9.9 V supply. (a) Calculate the combined capacitance. (b) Calculate the charge on each capacitor. (c) Calculate the number of electrons that flowed onto the plate connected to the negative terminal. (d) Explain why the inner plates are charged although they are not connected to the supply. Give only the answer to (c).' + take('e'), 1.1e-6 * 9.9 / QE, None,
  f'(a) C = 3.3 ÷ 3 = 1.1 µF. (b) Q = 1.1 × 10⁻⁶ × 9.9 = {sf(1.1e-6 * 9.9)} C. (c) N = {sf(1.1e-6 * 9.9, 4)} ÷ 1.60 × 10⁻¹⁹ = {sf(1.1e-6 * 9.9 / QE)}. (d) The charges on the outer plates attract or repel electrons in each isolated middle conductor, so its two plates gain equal and opposite charges.',
  ['C1: series C', 'C1: Q = CV', 'C1: N = Q/e', 'B1: induced charge separation', 'B1: isolated conductor stays neutral overall'], aq='N')
N('H', 5, 'Two capacitors give a combined capacitance of 2.4 µF in series and 10 µF in parallel. (a) Write two equations for the capacitances C₁ and C₂. (b) Show that C₁C₂ = 24 µF². (c) Find the larger capacitance, in µF. Give only the answer to (c).', 6.0, 'µF',
  '(a) C₁ + C₂ = 10 and C₁C₂/(C₁ + C₂) = 2.4. (b) C₁C₂ = 2.4 × 10 = 24. (c) C₁ and C₂ are the roots of C² − 10C + 24 = 0: C = (10 + √(10² − 4 × 24)) ÷ 2 = 6.0 µF; the other is 4.0 µF.',
  ['B1: both equations', 'M1: product = 2.4 × sum', 'C1: quadratic', 'C1: roots 6.0 and 4.0'], sig=2, aq='C')
